def design(brief, tools):
    import math
    g = float(brief.get("gravity", 9.81))
    rho = float(brief.get("air_density", 1.225))
    planet = brief.get("planet", "earth")
    if "planet" in brief and "gravity" not in brief and "air_density" not in brief:
        if planet == "mars":
            g = 3.71
            rho = 0.020
        elif planet == "titan":
            g = 1.35
            rho = 5.40
        else:
            g = 9.81
            rho = 1.225
    payload = float(brief.get("payload_kg", 0))
    endurance_min = float(brief.get("endurance_min", 0) or 0)
    distance_km = float(brief.get("distance_km", 0) or 0)
    max_span = brief.get("max_span_m", None)
    wind = float(brief.get("wind_m_s", 0) or 0)
    rain = brief.get("rain", False)

    # config choices
    frame_material = "carbon"
    battery_chemistry = "li-ion"
    # energy density kWh/kg and C-rate assumptions
    e_density = 0.25  # li-ion
    c_rate = 4.0
    ducted = False

    # rotors count: more rotors for heavier payload, fewer for tight span efficiency
    n = 4
    if payload >= 8:
        n = 6
    if payload >= 20:
        n = 8
    if max_span is not None and max_span < 1.0:
        n = 6
        ducted = True  # ducts reduce span

    # rotor diameter to fit span, conservative span model: span_est = 1.2*D*sqrt(n)+0.1 (+duct allowance)
    if max_span is not None:
        try:
            ms = float(max_span)
        except:
            ms = 1.6
        allow = ms * 0.88 - 0.1
        if ducted:
            allow -= 0.15
        if allow < 0.2:
            allow = 0.2
        D = allow / (1.2 * math.sqrt(n))
    else:
        # no span limit: size by payload / rho (mars needs big disks)
        D = 0.8 + payload * 0.05
        if rho < 0.1:
            D = 1.5 + payload * 0.1
        if rho > 3:
            D = 0.5 + payload * 0.02
    if D > 4.0:
        D = 4.0
    if D < 0.1:
        D = 0.1
    # clamp more for mars thin air: want max area
    if rho < 0.1 and max_span is not None:
        # use max allowed already
        pass

    A = n * math.pi * D * D / 4.0
    if A < 0.01:
        A = 0.01

    # iterative mass/power sizing
    # frame span estimate
    def span_est(D_, n_, ducted_):
        s = 1.2 * D_ * math.sqrt(n_) + 0.1
        if ducted_:
            s += 0.15
        return s
    span = span_est(D, n, ducted)

    # initial total mass guess
    total_mass = payload + 3.0 + n * 0.2
    # figure of merit + profile factor
    FM = 0.70
    prof_factor = 1.25
    if ducted:
        FM = 0.78  # ducts improve induced efficiency

    for _ in range(12):
        W = total_mass * g
        # momentum hover power
        try:
            P_ind = (W ** 1.5) / math.sqrt(2.0 * rho * A) / FM
        except:
            P_ind = W * 10.0
        P_hover = P_ind * 1.0 + W * 0.5 / 1000.0  # small extra
        # profile/power overhead
        P_hover = P_hover / 1000.0 * prof_factor  # kW
        if P_hover < 0.05:
            P_hover = 0.05
        if P_hover > 50:
            P_hover = 50.0
        # required battery for endurance
        if endurance_min > 0:
            e_end = P_hover * (endurance_min / 60.0) / 0.75 * 1.35
        else:
            e_end = P_hover * (10.0 / 60.0) / 0.75 * 1.2
        # mission with distance: trip energy approx
        cruise = 12.0
        if distance_km > 0:
            # pick efficient cruise: a bit faster for long range, slower in wind
            cruise = 14.0
            if wind > 8:
                cruise = 16.0
            if distance_km > 20:
                cruise = 18.0
            if cruise > 60:
                cruise = 60.0
            if cruise < 5:
                cruise = 5.0
            gs = cruise - 0.7 * wind
            if gs < 3:
                gs = 3.0
            t_h = distance_km * 1000.0 / gs / 3600.0  # hours
            # forward power ~ hover*0.8 + k*v^3 parasite (rough)
            P_cruise = P_hover * 0.85 + 0.0004 * cruise ** 3 * (1.225 / rho if rho > 0 else 1) * 0.3
            if rain:
                P_cruise *= 1.15
            e_trip = P_cruise * t_h / 0.75 * 1.35 + P_hover * (2.0 / 60.0) / 0.75
            e_end = max(e_end, e_trip)
        # power requirement: battery C must support ~2.2x hover
        e_pow = (2.3 * P_hover) / c_rate
        # rain waterproofing handled in mass loop below, add energy margin
        if rain:
            e_end *= 1.1
        e_need = e_end if e_end > e_pow else e_pow
        if e_need < 0.1:
            e_need = 0.1
        if e_need > 30:
            e_need = 30.0
        batt_mass = e_need / e_density
        # motor sizing for T/W: need >=1.837x hover, use 2.3x
        P_mot_total = 2.35 * P_hover
        mot_mass = P_mot_total * 0.20
        rot_mass = 0.35 * n * D * D
        if ducted:
            duct_mass = 0.9 * n * D * D + 0.2
        else:
            duct_mass = 0.0
        frame_mass = 1.15 * span + 0.15 * n
        if rain:
            wp = 0.07 * (payload + batt_mass + mot_mass + rot_mass + duct_mass + frame_mass)
        else:
            wp = 0.0
        new_total = payload + batt_mass + mot_mass + rot_mass + duct_mass + frame_mass + wp
        # damp iteration
        total_mass = 0.5 * total_mass + 0.5 * new_total
    # final values
    W = total_mass * g
    try:
        P_ind = (W ** 1.5) / math.sqrt(2.0 * rho * A) / FM
    except:
        P_ind = 500.0
    P_hover = P_ind / 1000.0 * prof_factor
    P_mot_total = 2.35 * P_hover
    mot_kw_each = P_mot_total / n * 1.15
    if mot_kw_each < 0.1:
        mot_kw_each = 0.1
    # recompute battery need with final hover
    if endurance_min > 0:
        e_end2 = P_hover * (endurance_min / 60.0) / 0.75 * 1.35
    else:
        e_end2 = P_hover * (10.0 / 60.0) / 0.75 * 1.2
    if distance_km > 0:
        gs = cruise - 0.7 * wind
        if gs < 3:
            gs = 3.0
        t_h = distance_km * 1000.0 / gs / 3600.0
        P_cruise = P_hover * 0.85 + 0.0004 * cruise ** 3 * 0.3
        if rain:
            P_cruise *= 1.15
        e_trip = P_cruise * t_h / 0.75 * 1.35 + P_hover * (2.0 / 60.0) / 0.75
        e_end2 = max(e_end2, e_trip)
    e_pow2 = (2.3 * P_hover) / c_rate
    batt_kwh = e_end2 if e_end2 > e_pow2 else e_pow2
    if rain:
        batt_kwh *= 1.1
    batt_kwh *= 1.1  # extra margin
    if batt_kwh < 0.1:
        batt_kwh = 0.1
    # ensure motor headroom even if hover grew due to battery margin
    # bump motors to cover battery-power-limited case
    # check span once more, shrink D if needed
    if max_span is not None and span > float(max_span) * 0.95:
        D = D * 0.92
        if D < 0.1:
            D = 0.1
    cruise_out = 12.0
    if distance_km > 0:
        cruise_out = cruise
    else:
        cruise_out = 12.0
    if cruise_out < 5:
        cruise_out = 5.0
    if cruise_out > 60:
        cruise_out = 60.0
    return {"n_rotors": int(n), "rotor_diameter_m": float(D), "motor_power_kw": float(mot_kw_each), "battery_kwh": float(batt_kwh), "battery_chemistry": str(battery_chemistry), "frame_material": str(frame_material), "ducted": bool(ducted), "cruise_speed_m_s": float(cruise_out)}
